OpenFaderIcon? openFaderIcon(String? id) {
  for (final icon in openFaderIcons) {
    if (icon.id == id) return icon;
  }
  return null;
}

enum ChannelIconKind { followProvider, none, catalog, imported }

/// Explicit None differs from absence of an OpenFader override.
class ChannelIconSelection {
  final ChannelIconKind kind;
  final String? id;
  const ChannelIconSelection.followProvider()
      : kind = ChannelIconKind.followProvider,
        id = null;
  const ChannelIconSelection.none()
      : kind = ChannelIconKind.none,
        id = null;
  const ChannelIconSelection.catalog(String this.id)
      : kind = ChannelIconKind.catalog;
  const ChannelIconSelection.imported(String this.id)
      : kind = ChannelIconKind.imported;
  Map<String, Object> toJson() =>
      {'kind': kind.name, 'id': ?id};
  static ChannelIconSelection fromJson(Object? raw) {
    if (raw is! Map) throw const FormatException('Invalid icon selection');
    final id = raw['id'];
    return switch (raw['kind']) {
      'followProvider' => const ChannelIconSelection.followProvider(),
      'none' => const ChannelIconSelection.none(),
      'catalog' when id is String && id.isNotEmpty =>
        ChannelIconSelection.catalog(id),
      'imported' when id is String && RegExp(r'^[a-f0-9]{64}$').hasMatch(id) =>
        ChannelIconSelection.imported(id),
      _ => throw const FormatException('Invalid icon selection'),
    };
  }

  @override
  bool operator ==(Object other) =>
      other is ChannelIconSelection && kind == other.kind && id == other.id;
  @override
  int get hashCode => Object.hash(kind, id);
}

class ResolvedChannelIcon {
  final ChannelIconSelection selection;
  final String? imagePath, reason;
  const ResolvedChannelIcon(this.selection, {this.imagePath, this.reason});
}

enum ChannelIconNativeOutcome { notRequested, unavailable, accepted, failed }

class ChannelIconEditResult {
  final bool saved;
  final String message;
  final ChannelIconNativeOutcome native;
  const ChannelIconEditResult(this.saved, this.message,
      {this.native = ChannelIconNativeOutcome.notRequested});
}

